const item = $input.item;
if (item.binary && item.binary.data) {
  const meta = $('Current File').first().json;
  const base = (meta.fileName || 'document').replace(/\.[^.]+$/, '');
  item.binary.data.fileName = base + '.pdf';
  item.binary.data.fileExtension = 'pdf';
  item.binary.data.mimeType = 'application/pdf';
}
return item;

const meta = $('Current File').first().json;
const text = $input.all().map(i => (i.json.text || '')).join('\n').trim();
return [{ json: { text, fileId: meta.fileId, fileName: meta.fileName, access: meta.access || 'public' } }];

const src = $('Normalize Extracted Text').first().json;
const text = src.text || '';

// 2500 rather than 1000: every chunk is one embedding call, and the vector
// store embeds a whole file in one burst. Large documents generated enough
// calls to trip the Vertex per-minute limit by themselves, which is why
// slowing the FILE rate never fixed it. Bigger chunks cut calls per file by
// about 60%. Retrieval gets slightly less precise in exchange.
const chunkSize = 2500;
const overlap = 300;
const output = [];
if (!text.trim()) {
  // Scanned/image-only PDF with no text layer - emit a marker so the run continues and the file gets skipped
  return [{ json: { noText: true, fileId: src.fileId, fileName: src.fileName } }];
}

// Access is decided by the Drive folder name in 'Current File'. The document's
// own text is deliberately not consulted: a file is restricted because of where
// it lives, not because of what it says.
const access = src.access || 'public';

let start = 0;
let chunkIndex = 1;
while (start < text.length) {
  let end = start + chunkSize;
  if (end < text.length) {
    const lastSpace = text.lastIndexOf(' ', end);
    // Back off to a word boundary, but never more than halfway, so a sparse
    // stretch of text cannot collapse a chunk to almost nothing.
    if (lastSpace > start + 1250) { end = lastSpace; }
  }
  const chunk = text.slice(start, end).trim();
  if (chunk.length > 0) {
    output.push({ json: { text: chunk, chunkIndex, fileId: src.fileId, fileName: src.fileName, access } });
  }
  if (end >= text.length) { break; }
  start = end - overlap;
  chunkIndex++;
}
if (output.length === 0) {
  return [{ json: { noText: true, fileId: src.fileId, fileName: src.fileName } }];
}
return output;

// Image file (png/jpg): store it as base64 so the chatbot can display it
const meta = $('Current File').first().json;
const item = $input.first();
const mime = (item.binary && item.binary.data && item.binary.data.mimeType) || 'image/png';
const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
return [{ json: {
  file_id: meta.fileId,
  page: 1,
  file_name: meta.fileName,
  mime_type: mime,
  access: meta.access || 'public',
  image_base64: buf.toString('base64')
} }];

// Parse ConvertAPI JSON response: Files[] with base64 FileData per page
const meta = $('Current File').first().json;
const resp = $input.first().json || {};
const files = Array.isArray(resp.Files) ? resp.Files : [];
const out = [];
let page = 1;
for (const f of files.slice(0, 6)) {
  if (!f || !f.FileData) continue;
  out.push({ json: {
    file_id: meta.fileId,
    page: page,
    file_name: meta.fileName,
    mime_type: 'image/jpeg',
    access: meta.access || 'public',
    image_base64: f.FileData
  } });
  page++;
}
if (out.length === 0) {
  // Nothing converted - emit a no-op row (Insert skips empty image_base64)
  return [{ json: { file_id: meta.fileId, page: 1, file_name: meta.fileName, mime_type: 'image/jpeg', access: meta.access || 'public', image_base64: '' } }];
}
return out;

// Collect the stored page images for the CURRENT file and turn them into binary items for Gemini OCR
const cur = $('Current File').first().json;
function rowsFrom(name) {
  try {
    return $(name).all().map(i => i.json || {}).filter(r => r.file_id === cur.fileId && r.image_base64);
  } catch (e) { return []; }
}
let rows = rowsFrom('Store Scan Page Images');
if (!rows.length) rows = rowsFrom('Store Image File');
rows = rows.slice(0, 6);
if (!rows.length) {
  return [{ json: { noImages: true } }];
}
const out = [];
for (const r of rows) {
  const bin = await this.helpers.prepareBinaryData(Buffer.from(r.image_base64, 'base64'), 'page-' + r.page + '.jpg', r.mime_type || 'image/jpeg');
  out.push({ json: { page: r.page, noImages: false }, binary: { data: bin } });
}
return out;

// Join per-page OCR text, then chunk it exactly like the normal text pipeline
const cur = $('Current File').first().json;
const pages = $input.all().map(i => i.json || {});
let full = pages.map((p, idx) => {
  const t = ((p.text || p.output || p.response || '') + '').trim();
  return t ? '[Page ' + (idx + 1) + ']\n' + t : '';
}).filter(Boolean).join('\n\n').trim();

if (full.length < 40) {
  // Photo/image with no meaningful text - image is stored, nothing to index
  return [{ json: { noOcr: true } }];
}

full = 'OCR transcription of scanned document: ' + (cur.fileName || '') + '\n\n' + full;

// Access is decided by the Drive folder name in 'Current File', same as the
// normal text pipeline. The OCR'd content is not consulted.
const access = cur.access || 'public';

// Kept in step with 'Chunk KB Text'. See the note there: chunk count drives
// embedding calls, and large files were exhausting the Vertex per-minute quota.
const chunkSize = 2500, overlap = 300;
const out = [];
let start = 0, chunkIndex = 1;
while (start < full.length) {
  let end = start + chunkSize;
  if (end < full.length) {
    const ls = full.lastIndexOf(' ', end);
    if (ls > start + 1250) end = ls;
  }
  const chunk = full.slice(start, end).trim();
  if (chunk.length > 0) {
    out.push({ json: { text: chunk, chunkIndex, fileId: cur.fileId, fileName: cur.fileName, access } });
  }
  if (end >= full.length) break;
  start = end - overlap;
  chunkIndex++;
}
if (!out.length) return [{ json: { noOcr: true } }];
return out;

