-- Deliberately NOT 'done'. These files produced no searchable text, either
-- because OCR failed or because the pages genuinely carry none. Marking them
-- done hid seven real documents in plain sight. 'no_text' is never re-claimed
-- by Claim Pending Files, so this does not loop, but it is visible with:
--   SELECT file_name FROM fc_kb_queue WHERE status = 'no_text';
UPDATE fc_kb_queue SET status = 'no_text', updated_at = now() WHERE file_id = $1;
